const upsertStorageProfile = `-- name: UpsertStorageProfile :exec
WITH input AS (
  SELECT
    $1::varchar(64) AS profile_id,
    $2::varchar(100) AS name,
    $3::varchar(50) AS provider,
    $4::boolean AS enabled,
    $5::boolean AS is_current,
    $6::boolean AS builtin,
    $7::varchar(32) AS status,
    $8::jsonb AS config,
    $9::bigint AS created_by,
    $10::bigint AS updated_by
)
INSERT INTO storage_profiles (
  profile_id, name, provider, enabled, is_current,
  builtin, status, config, created_by, updated_by
)
SELECT
  input.profile_id,
  input.name,
  input.provider,
  input.enabled,
  input.is_current,
  input.builtin,
  input.status,
  input.config,
  input.created_by,
  input.updated_by
FROM input
ON CONFLICT (profile_id) DO UPDATE
SET name = EXCLUDED.name,
    enabled = EXCLUDED.enabled,
    is_current = EXCLUDED.is_current,
    builtin = EXCLUDED.builtin,
    status = EXCLUDED.status,
    config = EXCLUDED.config,
    updated_by = EXCLUDED.updated_by,
    deleted_at = CASE WHEN EXCLUDED.status = 'deleted' THEN COALESCE(storage_profiles.deleted_at, now()) ELSE NULL END
`

type UpsertStorageProfileParams struct {
	ProfileID string          `json:"profile_id"`
	Name      string          `json:"name"`
	Provider  string          `json:"provider"`
	Enabled   bool            `json:"enabled"`
	IsCurrent bool            `json:"is_current"`
	Builtin   bool            `json:"builtin"`
	Status    string          `json:"status"`
	Config    json.RawMessage `json:"config"`
	CreatedBy sql.NullInt64   `json:"created_by"`
	UpdatedBy sql.NullInt64   `json:"updated_by"`
}

func (q *Queries) UpsertStorageProfile(ctx context.Context, arg UpsertStorageProfileParams) error {
	_, err := q.db.ExecContext(ctx, upsertStorageProfile,
		arg.ProfileID,
		arg.Name,
		arg.Provider,
		arg.Enabled,
		arg.IsCurrent,
		arg.Builtin,
		arg.Status,
		arg.Config,
		arg.CreatedBy,
		arg.UpdatedBy,
	)
	return err
}

const upsertSystemConfig = `-- name: UpsertSystemConfig :exec
INSERT INTO system_configs (config_key, value)
VALUES ($1, $2)
ON CONFLICT (config_key) DO UPDATE
SET value = EXCLUDED.value
`

type UpsertSystemConfigParams struct {
	ConfigKey string `json:"config_key"`
	Value     string `json:"value"`
}

func (q *Queries) UpsertSystemConfig(ctx context.Context, arg UpsertSystemConfigParams) error {
	_, err := q.db.ExecContext(ctx, upsertSystemConfig, arg.ConfigKey, arg.Value)
	return err
}
